-- Proposed production-specific allowlist; no purge authorization. Requires external consumer and structural sign-off.
BEGIN;
DO $$ BEGIN IF coalesce(current_setting('costing_retention.seed_reviewed_by',true),'')='' THEN RAISE EXCEPTION 'named reviewer required'; END IF; END $$;
